// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.barcodeimport timber.log.Timberimport com.roshan.persona.vision.ocr.RgbImageimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Barcode Scanner Engine (Module 6 v4 — Step 6.4). * * Wraps ML Kit Barcode Scanning for on-device barcode/QR detection. * * ## Supported Formats * *  - QR Code (most common — UPI payments, WiFi sharing, vCards) *  - Data Matrix (medical, aerospace) *  - PDF-417 (boarding passes, IDs) *  - Aztec (boarding passes, event tickets) *  - Code-128, Code-39, Code-93 (logistics) *  - EAN-13, EAN-8, UPC-A, UPC-E (retail product barcodes) *  - ITF (interleaved 2 of 5 — shipping) *  - Codabar (libraries, blood banks) * * ## Performance (per strategy v4) * *  - < 100 ms per frame on mid-range devices (ML Kit on-device) *  - < 50 ms on flagship *  - Real-time: 10-15 FPS scanning (vs 30 FPS object detection) * * ## Use Cases * *  - **UPI QR payments** (India-first) — scan merchant QR → open payment intent *  - **WiFi sharing** — scan WiFi QR → connect to network *  - **vCard exchange** — scan business card QR → add contact *  - **Product lookup** — scan EAN-13 → search online *  - **Boarding pass** — scan PDF-417 → extract flight info * * ## Testability * * Native ML Kit inference is abstracted via [BarcodeDetectorDelegate] interface. * Production: [MlKitBarcodeDetectorDelegate] wraps `com.google.mlkit:barcode-scanning`. * Tests: [FakeBarcodeDetectorDelegate] returns canned barcodes. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.4: BarcodeScannerEngine</a> */class BarcodeScannerEngine(    private val delegate: BarcodeDetectorDelegate,    private val payloadParser: QrPayloadParser,    private val dispatcher: CoroutineDispatcher,) {    /**     * Scan an image for barcodes/QR codes.     *     * @param frame the input image (RGB).     * @param formats barcode formats to scan for (default: all).     * @return tiered barcode scan result.     */    suspend fun scan(        frame: RgbImage,        formats: Set<BarcodeFormat> = BarcodeFormat.entries.toSet(),    ): TieredBarcodeResult = withContext(dispatcher) {        if (!delegate.isReady()) {            Timber.tag(TAG).w("Barcode detector not ready — returning empty result.")            val emptyResult = BarcodeScanResult(barcodes = emptyList(), processingTimeMs = 0)            return@withContext tieredBarcodeResult(emptyResult)        }        val startTime = System.currentTimeMillis()        val rawBarcodes = try {            delegate.detect(frame, formats)        } catch (t: Throwable) {            Timber.tag(TAG).e("Barcode scanning failed", t)            emptyList()        }        // Parse payloads for each barcode.        val parsedBarcodes = rawBarcodes.map { barcode ->            val parsed = payloadParser.parse(barcode.rawValue)            barcode.copy(                payloadType = parsed?.first ?: QrPayloadType.UNKNOWN,                parsedPayload = parsed?.second,            )        }        val elapsedMs = System.currentTimeMillis() - startTime        val result = BarcodeScanResult(            barcodes = parsedBarcodes,            processingTimeMs = elapsedMs,        )        Timber.tag(TAG).d("Barcode scan: ${parsedBarcodes.size} barcodes (${elapsedMs}ms).")        tieredBarcodeResult(result)    }    /**     * Scan for the first QR code only (faster — for payment flows).     *     * @param frame the input image.     * @return the first QR code found, or null.     */    suspend fun scanFirstQr(frame: RgbImage): BarcodeResult? = withContext(dispatcher) {        val result = scan(frame, setOf(BarcodeFormat.QR_CODE))        result.value?.firstQrCode    }    /** True if the detector is ready. */    fun isReady(): Boolean = delegate.isReady()    private companion object {        private const val TAG = "BarcodeScannerEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** Barcode detector delegate interface — abstracts ML Kit for testability. */interface BarcodeDetectorDelegate {    /** Detect barcodes in [frame]. Returns raw barcodes (pre-payload-parsing). */    suspend fun detect(frame: RgbImage, formats: Set<BarcodeFormat>): List<BarcodeResult>    /** True if the detector is ready. */    fun isReady(): Boolean}